import { AnswerOptionList } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function Question({ options, slide, hasSubmitted }) {
  const [picked, setPicked] = useState(null);
  return (
    <AnswerOptionList
      options={options}
      value={picked}
      onChange={setPicked}
      ink={slide.textColour}
      palette={slide.presentationColorPalette}
      answered={hasSubmitted}
    />
  );
}

import { AnswerOption } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

// Reach for AnswerOptionList first; this is the single row it repeats, for the
// rare screen that is not a list. The row is driven by answerOptionState(), never
// by working its own state out.
import { answerOptionState } from '@/iframe/audience';

export function Rows({ options, slide, palette, picked, setPicked, hasSubmitted, canShowResult }) {
  return options.map((o, i) => (
    <AnswerOption
      key={o.id}
      label={o.label}
      state={answerOptionState({
        quizStatus: slide.quizStatus,
        answered: hasSubmitted,
        revealed: canShowResult,
        selected: picked === o.id,
        correct: o.correct,
      })}
      ink={slide.textColour}
      accent={palette[i % palette.length]}
      onPick={() => setPicked(o.id)}
    />
  ));
}

import { DraggableOptions } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function Ordering({ options, slide, questionText, hasSubmitted }) {
  const [ordering, setOrdering] = useState(null);   // ordered id array
  return (
    <DraggableOptions
      options={options}
      value={ordering}
      onChange={setOrdering}
      ink={slide.textColour}
      palette={slide.presentationColorPalette}
      groupLabel={questionText}
      disabled={hasSubmitted}
    />
  );
}

