import { Timer } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function CountdownBar({ slide }) {
  return (
    <Timer
      ink={slide.textColour}
      endsAt={slide.stopSubmissionTime}   // absolute instant, not a duration
      totalMs={slide.timeToAnswer * 1000}
      stopped={slide.stopSubmission}
    />
  );
}

import { ScaleSlider } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function Scales({ statements, slide, palette, answers, setAnswer }) {
  return statements.map((row, i) => (
    <ScaleSlider
      key={row.id}
      value={answers[row.id]}
      onChange={(v) => setAnswer(row.id, v)}
      ink={slide.textColour}
      accent={palette[i % palette.length]}   // required, by position
      min={1}
      max={5}
      lowLabel={row.low}
      highLabel={row.high}
    />
  ));
}

import { Chip } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function Tags({ tags, slide, palette, picked, toggle }) {
  return tags.map((tag, i) => (
    <Chip
      key={tag.id}
      label={tag.label}
      selected={picked.includes(tag.id)}
      ink={slide.textColour}
      accent={palette[i % palette.length]}
      onClick={() => toggle(tag.id)}
    />
  ));
}

import { ImageUploader } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function PhotoAnswer({ slide, uploadImage, showToast }) {
  const [image, setImage] = useState(null);
  return (
    <ImageUploader
      value={image}
      onChange={setImage}
      uploadImage={uploadImage}   // the HOST performs the upload
      ink={slide.textColour}
      onError={showToast}
    />
  );
}

import { SubmitButton } from '@/iframe/audience';   // same marketplace package
import { useState } from 'react';

export function Submit({ slide, palette, sending, picked, submissionsClosed, submit }) {
  return (
    <SubmitButton
      ink={slide.textColour}
      accent={palette[0]}   // deck's first palette colour
      loading={sending}
      disabled={!picked}
      submissionClosed={submissionsClosed}
      closedLabel="Submissions closed"
      onClick={submit}
    >
      Submit
    </SubmitButton>
  );
}

